powerpagecomponent.content:
{
  "source": "{% comment %}
  Outcome Testing page shell.
  Every portal page extends this and fills the "content" block.
  Usage: extends 'OT Layout', then a block named content.

  Header, navigation and footer come from the site's header/footer templates;
  outcome-testing.css restyles those to Ascot Lloyd brand values.
{% endcomment %}

{% comment %}
  Roundo is the brand's single primary font (brand/ typography sheet),
  served from Fontshare, the source the sheet itself names. Weights are
  Light 300, Regular 400, Medium 500, SemiBold 600.

  The stylesheet carries a version querystring so a browser holding the
  previous file picks up changes without a hard refresh. Bump it on EVERY
  change to outcome-testing.css, not only a material one - a browser holding
  the old file is not told what changed, and the deploy succeeds either way, so
  the omission looks exactly like a CSS rule that does not work. That is how a
  border fix for the remediation Reason and Notes fields shipped to DEV twice
  on 2026-09-11 and was reported both times as not showing.
{% endcomment %}
<link rel="preconnect" href="https://api.fontshare.com" crossorigin>
<link rel="preconnect" href="https://cdn.fontshare.com" crossorigin>
<link rel="stylesheet" href="https://api.fontshare.com/v2/css?f[]=roundo@300,400,500,600&display=swap">
<link rel="stylesheet" href="/outcome-testing.css?v=28">

<main class="ot-page" id="ot-main">
  <div class="ot-page__inner">

    {% unless page.url == '/' %}
      <nav class="ot-breadcrumb" aria-label="Breadcrumb">
        <a href="/">Home</a>
        <span aria-hidden="true">/</span>
        <span aria-current="page">{{ page.title | escape }}</span>
      </nav>
    {% endunless %}

    <header class="ot-page__header">
      <h1 class="ot-page__title">{{ page.title | escape }}</h1>
      {% if page.summary and page.summary != empty %}
        <p class="ot-page__lede">{{ page.summary }}</p>
      {% endif %}
    </header>

    {% unless user %}
      <div class="ot-notice" role="status">
        You are not signed in.
        <a href="{{ website.sign_in_url_substitution }}">Sign in</a> to see your work.
      </div>
    {% endunless %}

    {% block content %}{% endblock %}

  </div>
</main>

{% comment %}
  A text box prints at its screen height and hides the rest of a long answer, in portrait
  and in landscape; a one-line field cuts a long value off at its edge. While the page
  prints, each filled box, and each one-line field whose value does not fit, is stood in
  for by a plain copy of its text, which wraps to the paper and grows; the print rules in
  outcome-testing.css hide the field and show the copy. An empty box is left as it is, so
  the form still prints a space to write in. Everything is undone after the print.
{% endcomment %}
<script>
  (function () {
    'use strict';

    // The box being typed in when the print started: hiding it drops the focus, so it is
    // handed back afterwards.
    var typingIn = null;

    function clear() {
      var copies = document.querySelectorAll('.ot-print-copy');
      for (var i = 0; i < copies.length; i++) { copies[i].parentNode.removeChild(copies[i]); }
      var boxes = document.querySelectorAll('.ot-printed-as-copy');
      for (var j = 0; j < boxes.length; j++) { boxes[j].classList.remove('ot-printed-as-copy'); }
      if (typingIn && document.body.contains(typingIn) && document.activeElement !== typingIn) {
        try { typingIn.focus({ preventScroll: true }); } catch (e) { /* nothing to restore */ }
      }
      typingIn = null;
    }

    function copy() {
      var active = document.activeElement;
      var held = typingIn;
      typingIn = null;
      clear();
      typingIn = held || (active && (active.tagName === 'TEXTAREA' || active.tagName === 'INPUT') ? active : null);
      var boxes = document.querySelectorAll('textarea, input[type="text"], input[type="email"]');
      for (var i = 0; i < boxes.length; i++) {
        var box = boxes[i];
        if (!box.value) { continue; }
        // A one-line field is copied only when its value already runs past its edge; one
        // that fits prints as it is.
        if (box.tagName === 'INPUT' && box.scrollWidth <= box.clientWidth + 1) { continue; }
        var stand = document.createElement('div');
        // Ruled where the box is ruled on screen (the remediation form), unruled where it
        // is not (the checklist).
        var ruled = parseFloat(window.getComputedStyle(box).borderTopWidth) > 0;
        stand.className = ruled ? 'ot-print-copy ot-print-copy--ruled' : 'ot-print-copy';
        stand.setAttribute('aria-hidden', 'true');
        if (box.id) { stand.setAttribute('data-ot-print-copy-of', box.id); }
        stand.textContent = box.value;
        box.parentNode.insertBefore(stand, box.nextSibling);
        box.classList.add('ot-printed-as-copy');
      }
    }

    window.addEventListener('beforeprint', copy);
    window.addEventListener('afterprint', clear);

    // The same switch from the print media query, for a browser that prints without
    // raising the two events. Both paths are safe to run twice.
    if (window.matchMedia) {
      var paper = window.matchMedia('print');
      var onPaper = function (e) { if (e.matches) { copy(); } else { clear(); } };
      if (paper.addEventListener) { paper.addEventListener('change', onPaper); }
      else if (paper.addListener) { paper.addListener(onPaper); }
    }
  })();
</script>
"
}
